W += [
E('semiconductor','英 /ˌsemikənˈdʌktə/；美 /ˌsemikənˈdʌktər/','半导体；半导体器件','像能调节通行程度的道路：材料的导电表现可以被精细改变，因此适合做电子器件。','semi- 部分、介于其间 + conductor 导体；英语用已有成分构成科学名称。这里的半描述材料类别，不是一个固定的百分之五十。',SEMI+[['英语 semi- + conductor → semiconductor','从部分导电的名称发展为现代半导体材料及器件术语']],'silicon is a semiconductor 是说硅属于半导体材料。添加少量特定杂质等手段能改变导电性；新闻里的 semiconductor industry 指半导体产业，常围绕芯片及相关制造。','semiconductor materials；the semiconductor industry；semiconductor manufacturing。','conductor 容易导电，insulator 阻碍导电；semiconductor 的价值在于导电特性可调控，不是导线只能工作一半时间。',('Silicon is widely used as a semiconductor.','硅被广泛用作半导体。'),('The region has invested in semiconductor manufacturing.','该地区投资了半导体制造业。'),sources=['https://en.wiktionary.org/wiki/semiconductor#English','https://www.nist.gov/semiconductors','https://volga.eng.yale.edu/teaching-resources/semiconductors']),
E('semiconducting','/ˌsemikənˈdʌktɪŋ/','具有半导体性质的','把某种材料的导电特性标出来，而不是给一件现成芯片起名字。','semi- + conducting 导电的，英语构成形容词；和 semiconductor 名词平行，不必假设先有现代芯片名称再倒推出这个词。',SEMI+[['英语 semi- + conducting → semiconducting','部分导电、具有半导体性质的形容词'],['现代材料科学使用 semiconducting','描述材料或层的半导体特性']],'a semiconducting layer 是半导体层；semiconducting polymers 是具有半导体性质的聚合物。-ing 在这里通常是性质形容词，不是在说材料此刻忙着做一个动作。','semiconducting materials；a semiconducting layer；semiconducting polymers。','semiconductor 常是名词；semiconducting 是形容词。conducting 只说导电，不自动等于具有半导体的特性。',('The device contains a thin semiconducting layer.','这个器件含有一层很薄的半导体层。'),('The team studies semiconducting polymers for flexible electronics.','团队研究用于柔性电子器件的半导体聚合物。'),sources=['https://www.collinsdictionary.com/dictionary/english/semiconducting','https://en.wiktionary.org/wiki/semiconducting#English','https://www.nist.gov/semiconductors']),
E('semicolon','英 /ˌsemiˈkəʊlən/；美 /ˈsemikoʊlən/','分号','两句话联系很紧，逗号又显得接不稳时，可以用这个“；”把它们接起来。','semi- 半 + colon 冒号；是拉丁来源前缀与希腊来源名称组合的英语词。colon 的标点义又联系古代对句子部分的划分。',SEMI+[['英语 colon 冒号 + semi- → semicolon','形成分号名称；并非把英文 colon 的字母切成一半']],'分号可连接关系密切的独立分句，也能分隔内部已有逗号的复杂列举项。它不是“哪里想停一停都能放”的装饰。','use a semicolon；separate clauses with a semicolon；a misplaced semicolon。','colon 常引出解释、名单等；semicolon 常连接两个完整而紧密相关的分句。comma 的作用更轻，不能无条件替代分号连接完整句子。',('A semicolon would work well between these two clauses.','这两个分句之间用分号很合适。'),('The editor replaced the comma with a semicolon.','编辑把逗号改成了分号。'),sources=['https://www.etymonline.com/word/semicolon','https://en.wiktionary.org/wiki/semicolon#English']),
E('semifinalist','/ˌsemiˈfaɪnəlɪst/','半决赛选手；进入半决赛的队伍或人','已经走到决赛前一轮，离最后争冠还差一步。','可按 semifinal 半决赛 + -ist 参与者理解，也可分析 semi- + finalist；都是英语已有成分构词，不是整词从古拉丁借入。',SEMI+[['英语 semi- + final → semifinal；加人员后缀 -ist → semifinalist','参加半决赛的人或队伍；也可按 semi- + finalist 分析']],'a former semifinalist 是曾进半决赛的选手；通常单淘汰赛会有四个半决赛席位，但有的比赛制度不同，不应把词义固定成任何赛事的四强。','a tournament semifinalist；a former semifinalist；reach the tournament as a semifinalist。','finalist 已进入决赛；semifinalist 到了半决赛。进入半决赛不说明最终赢了这轮。',('Last year’s semifinalist was eliminated in the first round.','去年的半决赛选手在首轮就被淘汰了。'),('The four semifinalists attended a joint press conference.','四位半决赛选手出席了联合记者会。'),sources=['https://en.wiktionary.org/wiki/semifinalist#English','https://www.merriam-webster.com/dictionary/semifinalist']),
E('semiarid','/ˌsemiˈærɪd/','半干旱的','这个地方总体缺水、偏干，但又没到更极端的干旱程度。','semi- 部分、不完全 + arid 干旱的；英语直接构成气候和地理形容词。半不是每年只下一半时间的雨。',SEMI+[['英语 semi- + arid → semiarid','形成偏干、雨量有限的气候类别名称']],'a semiarid region 是半干旱地区，常见草地、灌丛等植被；具体分类还需看降水、蒸发等条件，不能只拿某一次下雨判断。','a semiarid climate；semiarid regions；farming in semiarid areas。','arid 更强调干旱；semiarid 相对没那么极端。dry day 只说一天的天气，semiarid climate 说较长期的气候特征。',('The village lies in a semiarid region.','这个村庄位于半干旱地区。'),('Farmers in semiarid areas often face long periods without rain.','半干旱地区的农民经常面临长时间无雨。'),sources=['https://www.collinsdictionary.com/dictionary/english/semiarid','https://en.wiktionary.org/wiki/semiarid#English']),
E('semiconscious','英 /ˌsemiˈkɒntʃəs/；美 /ˌsemiˈkɑːntʃəs/','半清醒的；意识不完全清楚的','还能有些反应，却没有完全清醒、清楚地理解周围发生什么。','semi- 部分 + conscious 有意识的；英语直接形成表示意识程度的形容词。不是把意识量化成正好一半。',SEMI+[['英语 semi- + conscious → semiconscious','部分清醒、反应不完全的状态']],'a semiconscious patient 是意识不完全清楚的患者；新闻描写也可用 found semiconscious。它通常比单纯困倦更重，不宜把每个打哈欠的人都这样形容。','remain semiconscious；a semiconscious patient；in a semiconscious state。','unconscious 指失去意识；semiconscious 表示仍有部分意识。sleepy 只是想睡觉，不自动等于意识受损。',('The report described him as semiconscious when he was found.','报告说，他被发现时处于半清醒状态。'),('She was semiconscious and responded only faintly to her name.','她意识不完全清楚，听到名字时只有微弱反应。'),sources=['https://dictionary.cambridge.org/pronunciation/english/semiconscious','https://www.merriam-webster.com/dictionary/semiconscious','https://en.wiktionary.org/wiki/semiconscious#English']),
E('seminatural','英 /ˌsemiˈnætʃərəl/','半自然的','仍保留自然生态的样子和成分，同时已经受到人的使用、管理或改造。','semi- 部分 + natural 自然的；现代英语用来描述自然过程与人为影响并存的状态。',SEMI+[['英语 semi- + natural → seminatural','形成部分自然、部分受到人为影响的形容词']],'seminatural grassland 可指经放牧或割草维持、又保留丰富自然植被的草地。它不是把土地机械地切成一半自然、一半水泥。','seminatural grassland；seminatural woodland；a seminatural habitat。','natural 强调自然形成或自然状态；seminatural 承认人为影响。artificial 则更突出人工制造，不能简单当作同义词。',('The survey recorded wildflowers in seminatural grassland.','调查记录了半自然草地中的野花。'),('The project aims to protect the area’s seminatural woodland.','这个项目旨在保护该地区的半自然林地。'),sources=['https://www.collinsdictionary.com/dictionary/english/seminatural','https://en.wiktionary.org/wiki/seminatural#English']),
E('semiautomatic','英 /ˌsemiˌɔːtəˈmætɪk/；美 /ˌsemiˌɔtəˈmætɪk/','半自动的','一部分步骤机器自己完成，另一部分还需要人来做或确认。','semi- 部分 + automatic 自动的；英语直接构成设备或操作方式的名称，半不要求自动和人工步骤数量恰好相等。',SEMI+[['英语 semi- + automatic → semiautomatic','部分自动、部分由人控制的状态']],'a semiautomatic machine 是半自动机器。新闻谈枪械时，这个词有专门含义：自行完成装填，但每次扣动扳机只发射一发；不能与全自动混为一词。','a semiautomatic machine；semiautomatic operation；a semiautomatic process。','manual 靠人工，automatic 自动；semiautomatic 位于二者之间。具体哪些步骤自动，要看设备说明。',('The factory replaced the manual machine with a semiautomatic model.','工厂用一台半自动型号替换了手动机器。'),('The process is semiautomatic: staff still check each batch.','这个流程是半自动的，员工仍需检查每一批产品。'),sources=['https://www.collinsdictionary.com/dictionary/english/semiautomatic','https://www.merriam-webster.com/dictionary/semiautomatic']),
E('semitransparent','英 /ˌsemitrænsˈpærənt/；美 /ˌsemitrænsˈperənt/','半透明的','隔着它还能看见后面的颜色或轮廓，但视线不如隔着透明玻璃那么清楚。','semi- 部分 + transparent 透明的；英语构成程度形容词，不是对透光率作固定的百分之五十规定。',SEMI+[['英语 semi- + transparent → semitransparent','部分透明、不完全遮住背后的事物']],'a semitransparent curtain 是半透明窗帘；界面设计中 semitransparent overlay 是能透出下面内容的半透明覆盖层。','semitransparent glass；a semitransparent curtain；a semitransparent overlay。','transparent 清晰透视，opaque 不透明。translucent 常强调光能透过但图像不清；日常用法与 semitransparent 有重叠。',('A semitransparent curtain softened the light from the window.','半透明窗帘柔化了窗外照进来的光。'),('The menu appears on a semitransparent panel.','菜单显示在一块半透明面板上。'),sources=['https://www.collinsdictionary.com/dictionary/english/semitransparent','https://www.merriam-webster.com/dictionary/semitransparent']),
]
